-- Полное сравнение INITIAL с исходным parsed STG, включая точный текст payload и исходные batch_id.
SELECT count(*) AS n FROM ((SELECT batch_id,topic,kafka_partition,kafka_offset,event_json,schema_version,event_id,event_type,entity_id,entity_version,op,event_time,payload FROM {{source:oil_stg__v_event_parsed}} EXCEPT ALL SELECT batch_id,topic,kafka_partition,kafka_offset,event_json,schema_version,event_id,event_type,entity_id,entity_version,op,event_time,payload FROM {{target:oil_stg__v_event_parsed}}) UNION ALL (SELECT batch_id,topic,kafka_partition,kafka_offset,event_json,schema_version,event_id,event_type,entity_id,entity_version,op,event_time,payload FROM {{target:oil_stg__v_event_parsed}} EXCEPT ALL SELECT batch_id,topic,kafka_partition,kafka_offset,event_json,schema_version,event_id,event_type,entity_id,entity_version,op,event_time,payload FROM {{source:oil_stg__v_event_parsed}})) q;
